// =============================================================================
// HIGH-LEVEL BUILDERS (Mode B convenience)
// =============================================================================
// These builders mirror the MCP wrapper shapes (`generate_report_docx`,
// `generate_invoice_docx`, `generate_contract_docx`) so a JSON spec written
// against the MCP server can be rendered locally with one call:
//
//   const doc = buildReportDocx({ title: '...', sections: [...] });
//   const result = await renderToDocx(doc);
//
// They produce canonical `DocxDocument` JSON — the same value the renderer
// accepts directly — so you can post-process the spec before rendering.
export {
  buildReportDocx,
  buildInvoiceDocx,
  buildContractDocx,
} from './builders/index.js';
