// =============================================================================
// PVCE CHARTING ENGINE
// =============================================================================

const pvce: DocxPvce = {
  ...(pvceRaw as Record<string, unknown>),
  compileChart(...args: unknown[]) {
    return pvceRaw.compileChart(...args as Parameters<typeof pvceRaw.compileChart>);
  },
  chartToSVG(...args: unknown[]) {
    return pvceRaw.chartToSVG(...args as Parameters<typeof pvceRaw.chartToSVG>);
  },
};

